const headers = $input.first().json.headers || {};
const lower = Object.fromEntries(Object.entries(headers).map(([k, v]) => [String(k).toLowerCase(), v]));
const token = String(lower['x-tradesejon-secret'] || lower['x-operator-token'] || lower['x-ceo-token'] || '');
const expected = String($env.WORKSHOP_LAUNCH_TOKEN || $env.TRADESAJON_BRIDGE_SECRET || '');
if (!expected || token !== expected) {
  return [{ json: { ok: false, authorized: false, httpStatus: 401, error: 'unauthorized' } }];
}
const body = $input.first().json.body || $input.first().json || {};
return [{ json: { ok: true, authorized: true, body } }];

const item = $input.first().json;
if (!item.authorized) return [{ json: item }];
const b = item.body || {};
const q = String(b.question || '').trim();
const isPaid = Boolean(b.paid);
const blockedKw = ['blueprint','masterclass','business model canvas','marketing plan','visual identity','1omga0wt','1c7gz7rw','المخطط الاستراتيجي','دليل الماستركلاس','خطة التسويق','الهوية البصرية','مجلد المستندات'];
if (!isPaid && blockedKw.some((k) => q.toLowerCase().includes(k))) {
  return [{ json: { ok: true, blocked: true, reply: '🔒 الملفات والمستندات الخاصة والمدفوعة متاحة فقط للمشتركين بعد تأكيد الاشتراك والدفع عبر Whop.' } }];
}
return [{ json: { ok: true, blocked: false, question: q, user_id: String(b.discord_user_id || ''), isPaid } }];
